import { useEffect, useState } from "react";

export default function Enquiries() {
  const [enquiries, setEnquiries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // ================= FETCH ENQUIRIES =================
  const fetchEnquiries = async () => {
    try {
      const token = localStorage.getItem("adminToken");

      if (!token) {
        setError("Admin not authenticated");
        setLoading(false);
        return;
      }

      const res = await fetch("http://localhost:5001/admin/enquiries", {
        headers: {
          Authorization: "Bearer " + token,
        },
      });

      if (!res.ok) {
        throw new Error("Failed to fetch enquiries");
      }

      const data = await res.json();

      // 🔥 SAFETY CHECK
      if (Array.isArray(data)) {
        setEnquiries(data);
      } else {
        setEnquiries([]);
      }
    } catch (err) {
      console.error("❌ Enquiries load error:", err);
      setError("Failed to load enquiries");
    } finally {
      setLoading(false);
    }
  };

  // LOAD ALWAYS ON PAGE OPEN / REFRESH
  useEffect(() => {
    fetchEnquiries();
  }, []);

  // ================= UPDATE STATUS =================
  const updateStatus = async (id, status) => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(
        `http://localhost:5001/admin/enquiries/${id}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + token,
          },
          body: JSON.stringify({ status }),
        }
      );

      if (!res.ok) {
        throw new Error("Update failed");
      }

      // ✅ INSTANT UI UPDATE
      setEnquiries((prev) =>
        prev.map((e) =>
          e.id === id ? { ...e, status } : e
        )
      );
    } catch (err) {
      console.error("❌ Status update error:", err);
    }
  };

  // ================= UI =================
  return (
    <div className="p-10 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-8">
        Customer Enquiries
      </h1>

      {loading ? (
        <p className="text-gray-400">Loading enquiries...</p>
      ) : error ? (
        <p className="text-red-400">{error}</p>
      ) : enquiries.length === 0 ? (
        <p className="text-gray-500">No enquiries found</p>
      ) : (
        <div className="space-y-6 max-w-5xl">
          {enquiries.map((e) => (
            <div
              key={e.id}
              className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
                         border border-yellow-500/30 rounded-2xl
                         p-6 shadow-xl hover:border-yellow-400 transition"
            >
              {/* HEADER */}
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-semibold text-yellow-400">
                  {e.name}
                </h2>

                <span
                  className={`text-xs px-3 py-1 rounded-full font-semibold ${
                    e.status === "New"
                      ? "bg-blue-500/20 text-blue-400"
                      : e.status === "Contacted"
                      ? "bg-yellow-500/20 text-yellow-400"
                      : e.status === "Joined"
                      ? "bg-green-500/20 text-green-400"
                      : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {e.status}
                </span>
              </div>

              {/* DETAILS */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2 text-sm text-gray-300 mb-4">
                <p>
                  <span className="text-gray-400">Phone:</span>{" "}
                  {e.phone}
                </p>
                <p>
                  <span className="text-gray-400">Email:</span>{" "}
                  {e.email}
                </p>
                <p>
                  <span className="text-gray-400">Branch:</span>{" "}
                  {e.branch}
                </p>
                <p>
                  <span className="text-gray-400">Intent:</span>{" "}
                  {e.intent}
                </p>
              </div>

              {/* MESSAGE */}
              <div className="bg-black/40 p-4 rounded-lg text-gray-200 text-sm mb-4">
                {e.message}
              </div>

              {/* FOOTER */}
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <p className="text-xs text-gray-500">
                  {new Date(e.created_at).toLocaleString()}
                </p>

                <div className="flex gap-2">
                  <button
                    onClick={() => updateStatus(e.id, "Contacted")}
                    className="px-4 py-1 bg-yellow-500 text-black text-xs rounded-lg font-semibold hover:bg-yellow-600"
                  >
                    Contacted
                  </button>

                  <button
                    onClick={() => updateStatus(e.id, "Joined")}
                    className="px-4 py-1 bg-green-500 text-black text-xs rounded-lg font-semibold hover:bg-green-600"
                  >
                    Joined
                  </button>

                  <button
                    onClick={() => updateStatus(e.id, "Closed")}
                    className="px-4 py-1 bg-red-500 text-black text-xs rounded-lg font-semibold hover:bg-red-600"
                  >
                    Closed
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
